unsafe fn img_hash(h: u64, img: &[u8], d: &[ODesc]) -> u64 {
    let mut tmp: std::vec::Vec<u8> = img.to_vec();
    onorm(&mut tmp, d);
    for &(off, size, kind) in d { if kind == b'b' { for j in 0..size as usize { tmp[off as usize + j] = 0; } } }
    fnv(h, &tmp)
}
unsafe fn word_hash(mut h: u64, img: &[u8]) -> u64 {
    let mut i = 0;
    while i + 8 <= img.len() {
        let mut w = u64::from_le_bytes(img[i..i + 8].try_into().unwrap());
        for &(b, n) in OREGS.iter() {
            if w > 0xFFFF_FFFF && (w as usize) >= b && (w as usize) < b + n {
                w = normptr(w as usize);
                break;
            }
        }
        h = fnv(h, &w.to_le_bytes());
        i += 8;
    }
    h
}
